parms.snippet:
int active_bits[] = detail(1, "active_bits");
int temporary_bits[] = detail(1, "temporary_bits");

int page_num = shr(@primnum, 10);
int page_offset = @primnum & 1023;

int which_int = shr(page_offset, 5) + shl(page_num,5);

int active = (active_bits[which_int] & shl(1, page_offset & 31)) != 0;
int temporary = (temporary_bits[which_int] & shl(1, page_offset & 31)) != 0;

int offset_size = detail(1, "offset_size");

if (@primnum >= offset_size) {
    v@Cd = 0;
} else if (active) {
    v@Cd = {0,1,0};
} else if (temporary) {
    v@Cd = {1,0,0};
} else if (active & temporary) {
    v@Cd = {1,1,1};
}

int pages = detail(1, "num_pages");

i@columns = max(5,int(ceil(sqrt(pages))));
i@rows = int(ceil(float(pages)/@columns));
i@attrib_spacers = detail(1, "attribs_reported");

@col_pad = 0.1;
@row_pad = 0.05 + 0.15 * i@attrib_spacers;

tags.script_action:
def unlockAll(node):
    for parm in node.parmTuples():
        parm.lock(False)

def updateLockValues(node):
    ## Determine our parameter override, if any.
    overrideparm = node.parm('spare_parminputindex')
    if overrideparm is None:
        return
    overrideidx = overrideparm.evalAsInt()
    if overrideidx >= 0:
        unlockAll(node)
        return
    overrideidx = - overrideidx - 1
    ## Get the wired input, if any.
    inputparmname = 'spare_input' + str(overrideidx)
    inputparm = node.parm(inputparmname)
    if inputparm is None:
        unlockAll(node)
        return
    inputpath = inputparm.evalAsString()
    inputnode = node.node(inputpath)
    if inputnode is None:
        unlockAll(node)
        return
    ## Determine if there is geometry and if it has an override dictionary
    if not isinstance(inputnode, hou.SopNode):
        return
    geo = inputnode.geometry()
    if geo is None:
        return
    parmattrib = geo.findGlobalAttrib('parms')
    if parmattrib is None:
        return
    if parmattrib.dataType() != hou.attribData.Dict:
        return
    ## correct override of dictionary type, fetch it.
    parmdict = geo.dictAttribValue('parms')

    ## Ensure all is unlocked
    unlockAll(node)

    ## Copy values over
    try:
        node.setParms(parmdict)
    except hou.Error:
        pass

    ## Lock each matching parm
    for parm in node.parmTuples():
        if parm.name() in parmdict:
            parm.lock(True)
        else:
            parm.lock(False)

node = kwargs['node']
updateLockValues(node)

